/**
 * "Remembered when due" and personal tuning (SRS v2 phase D): GET
 * /me/srs/stats, copied into meta `srsStats` so Progress and the schedule
 * page draw it on the first frame and say "as of" when offline. The counts
 * come from every device's answers, which is why they are the server's to
 * count; this device's own day totals only see its own.
 */
import { useCallback, useEffect, useRef, useState } from 'react';
import { trueRetention, type TrueRetention } from '@lexpad/core';
import { isApiError } from '@/api/errors.js';
import { me } from '@/api/endpoints.js';
import type { ApiSrsNotebookStats } from '@/api/types.js';
import { db, getMeta, setMeta, type LexpadDb, type MetaShape } from '@/db/schema.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';

/**
 * The window the numbers cover. The spec's "over 30 days" (§1 D) is a
 * product definition the screens name ("last 30 days"), not a tunable.
 */
export const SRS_STATS_DAYS = 30;

/**
 * How stale the copy may get before a screen that opens reads it again. A
 * client-side freshness choice: the numbers move by one answer at a time,
 * and a request on every visit to Progress would be waste.
 */
export const SRS_STATS_REFRESH_MS = 5 * 60_000;

export type StoredSrsStats = NonNullable<MetaShape['srsStats']>;

/** Reads the stats from the server and keeps a copy. Throws on failure; the copy stays. */
export async function refreshSrsStats(
  options: { force?: boolean; now?: Date } = {},
  database: LexpadDb = db,
): Promise<StoredSrsStats> {
  const now = options.now ?? new Date();
  const current = await getMeta('srsStats', database);
  if (
    options.force !== true &&
    current !== null &&
    now.getTime() - Date.parse(current.at) < SRS_STATS_REFRESH_MS
  ) {
    return current;
  }
  const stats = await me.srsStats(SRS_STATS_DAYS);
  const next = { at: now.toISOString(), stats };
  await setMeta('srsStats', next, database);
  return next;
}

/**
 * How the last read went: none answered yet (`idle`, which a screen with no
 * copy draws as loading), read now, offline, or failed.
 */
export type StatsFetch = 'idle' | 'fresh' | 'offline' | 'failed';

/**
 * The copy and how the last read went. It reads again when the screen
 * opens (unless the copy is fresh, or `force`) and when the app comes back
 * to the foreground; `enabled` false reads nothing (SRS v2 off for this
 * account).
 */
export function useSrsStats(
  enabled: boolean,
  /** Read again on open even when the copy is fresh: a page about these numbers. */
  force = false,
): {
  ready: boolean;
  stored: StoredSrsStats | null;
  fetch: StatsFetch;
} {
  const stored = useLiveQuery(
    async () => ({ ready: true, value: await getMeta('srsStats') }),
    { ready: false, value: null as StoredSrsStats | null },
    [],
  );
  const [fetch, setFetch] = useState<StatsFetch>('idle');
  const live = useRef(true);

  const load = useCallback((force: boolean): void => {
    refreshSrsStats({ force })
      .then(() => {
        if (live.current) setFetch('fresh');
      })
      .catch((cause: unknown) => {
        if (live.current) setFetch(isApiError(cause, 'offline') ? 'offline' : 'failed');
      });
  }, []);

  useEffect(() => {
    live.current = true;
    if (!enabled) return undefined;
    load(force);
    const onVisible = (): void => {
      if (document.visibilityState === 'visible') load(false);
    };
    document.addEventListener('visibilitychange', onVisible);
    return () => {
      live.current = false;
      document.removeEventListener('visibilitychange', onVisible);
    };
  }, [enabled, force, load]);

  return { ready: stored.ready, stored: stored.value, fetch };
}

/** The stats of the given notebooks, in the copy (a notebook it does not list has none yet). */
export function statsFor(
  stored: StoredSrsStats | null,
  notebookIds: readonly string[],
): ApiSrsNotebookStats[] {
  if (stored === null) return [];
  const wanted = new Set(notebookIds);
  return stored.stats.notebooks.filter((n) => wanted.has(n.notebookId));
}

/** True retention over the given notebooks. */
export function retentionFor(stored: StoredSrsStats | null, notebookIds: readonly string[]): TrueRetention {
  return trueRetention(statsFor(stored, notebookIds));
}
